let layer=0,data,player=new Audio(),end=0,serial=0;const names=['PAD','MELODIE','BASS','PULS'];const now=document.getElementById('now');function stop(){serial++;player.pause();document.querySelectorAll('.playing').forEach(b=>b.classList.remove('playing'));now.textContent='PRESET WÄHLEN ZUM VORHÖREN';}function draw(){document.getElementById('count').textContent='16 / '+names[layer];document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-selected',String(+b.dataset.layer===layer)));const grid=document.getElementById('sounds');grid.replaceChildren();data.sounds[layer].forEach((name,i)=>{const b=document.createElement('button');const num=document.createElement('small');num.textContent=String(i+1).padStart(2,'0')+' / PLAY';const title=document.createElement('span');title.textContent=name;b.append(num,title);b.onclick=async()=>{stop();const ticket=serial;const path='audio/layer-'+layer+'.wav';try{if(!player.src.endsWith(path)){player.src=path;await new Promise((ok,bad)=>{player.onloadedmetadata=ok;player.onerror=()=>bad(Error('Audiodatei konnte nicht geladen werden.'));player.load();});}if(ticket!==serial)return;player.currentTime=i*4;end=(i+1)*4;b.classList.add('playing');now.textContent=names[layer]+' / '+name;await player.play();}catch(e){if(ticket===serial)now.textContent=e.message;}};grid.append(b);});}player.ontimeupdate=()=>{if(!player.paused&&player.currentTime>=end)stop();};player.onended=stop;document.getElementById('stop').onclick=stop;document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{stop();layer=+b.dataset.layer;if(data)draw();});fetch('library.json').then(r=>{if(!r.ok)throw Error('Bibliothek nicht verfügbar');return r.json()}).then(x=>{data=x;draw();data.themes.forEach((name,i)=>{const el=document.createElement('div'),n=document.createElement('small');n.textContent=String(i+1).padStart(2,'0');el.append(n,document.createTextNode(name));document.getElementById('themes').append(el);});}).catch(e=>now.textContent=e.message);